value.stringValue:
Hi {!Applicant_Details.FirstName__c}, Your new Flexi Quote has been created: Quote Number: {!Get_Quote_Number_for_New_Quotes.QuoteNumber}
Please save this number—you can use it to resume your quote later or get help via our website.
Kind regards, Insurance Sales Team

formulas.expression:
IF( CONTAINS({!$Flow.FaultMessage} , '401') || CONTAINS({!$Flow.FaultMessage} , 'Unauthorized'), 
'We are currently experiencing technical difficulties with processing your request. Please try again later. If the problem persists, please contact us (Error code 401)',

IF(CONTAINS({!$Flow.FaultMessage} , '404') || CONTAINS({!$Flow.FaultMessage} , 'Not Found'), 
'We are currently experiencing technical difficulties with processing your request. Please try again later. If the problem persists, please contact us (Error code 404)', 

IF(CONTAINS({!$Flow.FaultMessage} , '503') || CONTAINS({!$Flow.FaultMessage} , 'Service Unavailable'), 
'We are currently experiencing technical difficulties with processing your request. Please try again later. If the problem persists, please contact us (Error code 503)', 

IF(CONTAINS({!$Flow.FaultMessage} , '504') || CONTAINS({!$Flow.FaultMessage} , 'Gateway Timeout'), 
'We are currently experiencing technical difficulties with processing your request. Please try again later. If the problem persists, please contact us (Error code 504)', 
''
)
)
)
)

IF(
    AND(
        NOT(ISBLANK({!recordId})),
        {!FSC_IS_THIS_QUOTE_TYPE_FOR_YOU_OR_SOMEONE_ELSE} = {!I_m_insuring_myself}
    ),
    TRUE,
    IF(
        AND(
            ISBLANK({!recordId}),
            {!QQT_IS_THIS_QUOTE_TYPE_FOR_YOU_OR_SOMEONE_ELSE} = {!I_m_insuring_myself}
        ),
        TRUE,
        FALSE
    )
)
